'use strict';
const E=id=>document.getElementById(id),safe=v=>String(v??'UNKNOWN').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v===null||v===undefined||v===''?NaN:Number(v), f=(v,n=2)=>Number.isFinite(number(v))?number(v).toFixed(n):'UNKNOWN', time=v=>/^\d{14}$/.test(String(v))?`${String(v).slice(8,10)}:${String(v).slice(10,12)}:${String(v).slice(12,14)}`:String(v||'UNKNOWN');
const datasetConfig=window.STOCK_DATASET_CONFIG||{},expectedStocks=datasetConfig.expectedStocks||85;const groups=datasetConfig.groups||[['今天新一轮回升候选_非买点确认','新一轮回升研究候选'],['已反弹延续_非历史首次','此前反弹延续'],['未收关键位或结构反证','待收回 / 风险'],['UNKNOWN','UNKNOWN']];let pack,category=groups[0][0],query='',showRetired=!!datasetConfig.showRetiredDefault,selectedSymbol='',chartLoadToken=0;const chartCache=new Map();
function overlay(s){const a=s.later1316_focus6_overlay||{},b=s.later1311_overlay||{};if(a.price!==undefined)return {price:a.price,time:a.quote_timestamp,amount:a.amount_yuan_source_f35,above:a.above_open,scope:'6股局部补充',gate:a.gate};if(b.new_price!==undefined)return {price:b.new_price,time:b.new_source,amount:null,above:b.above_open_now,scope:'15股局部补充',gate:b.still_pass_three===false?'THREE_GATES_FAILED':'RESEARCH_ONLY'};return null}
function latestQuote(s){const t=s.closeSnapshot?.snapshot;if(pack?.meta?.close_snapshot&&!t)return null;return t?{price:t.close,quote_timestamp:t.source_timestamp,received_at:t.capture_end_utc}:s.latest1332}
function gatePass(s){if(pack?.meta?.close_snapshot){const c=s.closeSnapshot;return !!c?.snapshot&&c.result==='PROVISIONAL_AT_OR_BELOW'&&c.amount_at_least_100m===true&&c.price_above_open===true&&c.raw_previous_matches_D26===true}return s.latest1332?.gate==='THREE_GATES_PASS_RESEARCH_ONLY'}
function latestBlock(s){if(pack?.meta?.close_snapshot&&!s.closeSnapshot?.snapshot)return '<div class="overlay negative">本股收盘快照UNKNOWN；不以13:32旧报价替代，不自动通过。</div>';if(s.closeSnapshot){const c=s.closeSnapshot,t=c.snapshot||{},reason=datasetConfig.kind==='breakout41'?'突破观察，回踩反包路径UNKNOWN（非买点认证）':c.result==='PROVISIONAL_AT_OR_BELOW'?'原价两门满足 + K高几何未超（PROVISIONAL条件观察）':c.result==='NOT_ABOVE_OPEN'?'价格不高于今开，暂退':c.result==='PROVISIONAL_ABOVE_OBSERVE_NO_CHASE'?'几何高于主K高，暂退不追':c.result==='BELOW_100M'?'成交额未达1亿元，暂退':'UNKNOWN，不能自动通过';return `<div class="overlay ${gatePass(s)?'':'negative'}"><strong>D27收盘后供应商快照：${f(t.close)} · ${reason}</strong><br>来源 ${safe(t.source_timestamp)} / 收到UTC ${safe(t.capture_end_utc)}<br>今开 ${f(t.open)} · 全日高/低 ${f(t.high)}/${f(t.low)} · 累计额 ${f(number(t.amount_yuan)/1e8,3)}亿元<br>收盘后供应商更新时间不是交易所最后成交时刻。关键K比较仅几何条件，公司行动未准入，不是确认买点；原关键K锚仍D26；图/白黄BBI截至 ${safe(s.displayProjection?.line_asof||'20261026')}，分位截至 ${safe(s.pricePosition85?.asof||'UNKNOWN')}。</div>`}const t=s.latest1332;if(!t)return '<div class="overlay negative">最新快照UNKNOWN，不自动通过</div>';const reason=t.gate==='NOT_ABOVE_OPEN'?'已≤今开，暂退':t.gate==='OBSERVE_NO_CHASE'?'已超主关键K高，暂退':gatePass(s)?'仍过三门，仅研究资格':'UNKNOWN，待核';const position=t.below_key_low_now===true?'仍低于静态关键K最低':t.below_key_body_now===true?'处于静态关键K最低之上/附近，但实体底尚未收回':'静态关键区域位置见参考，不等于承接确认';return `<div class="overlay ${!gatePass(s)||t.below_key_body_now?'negative':''}"><strong>最新 ${safe(time(t.quote_timestamp))}：${f(t.price)} · ${reason}</strong><br>今开 ${f(t.open)} · 累计额 ${f(number(t.amount_yuan_source_f35)/1e8,3)}亿元<br>${position}（低 ${f(s.key_low)} / 实体底 ${f(s.key_body_low)}）。QFQ与原价公司事件坐标未准入，仅研究提示；原结构反证继续有效。</div>`}
function historyBlock(s){const h=s.history24;if(!h)return '<p class="card-evidence">本股本轮完整历史统计未接入，不借用其他24股。</p>';const labels={union:'原信号并集',primary:'一级',secondary:'二级'};return `<details class="card-evidence"><summary>原式历史CC2/CC5 · 已核描述统计</summary><p>覆盖 ${safe(h.coverage_start)}–${safe(h.coverage_end)}，${safe(h.bars)}根。D收盘→市场+2/+5日收盘毛变化，非开盘交易法、非PIT；不是当前结构组合胜率。<strong>D26原信号未触发，当前精确同型N/A。</strong></p>${h.stats.filter(r=>Object.hasOwn(labels,r.group)).map(r=>`<div class="stat-row"><span>${labels[r.group]} CC${safe(r.horizon)}<br>成熟 ${safe(r.mature_valid)} / 总 ${safe(r.total)}<br>正/负/平 ${safe(r.positive)}/${safe(r.negative)}/${safe(r.flat)}<br>未成熟 ${safe(r.immature)} · 缺价 ${safe(r.missing_price)} · 无效 ${safe(r.invalid_price)}</span><span>原式历史正收益占比（非预测胜率） ${Number.isFinite(number(r.positive_fraction))?f(number(r.positive_fraction)*100)+'%':'UNKNOWN'}<br>中位毛收益 ${f(r.median_pct)}%<br>均值 ${f(r.mean_pct)}%</span></div>`).join('')}<p>仅缓存原信号历史端点统计验收；不认证当前买点。来源SHA ${safe(h.source_sha256)}</p></details>`}
function chartPreview(s){return s.chart_url?`<figure class="chart-preview"><button class="chart-preview-button" data-image="${safe(s.symbol)}" aria-label="放大${safe(s.name)}实际K线图"><img data-chart-thumb="${safe(s.symbol)}" src="${safe(s.chart_url)}" loading="lazy" decoding="async" alt="${safe(s.name)} ${safe(s.symbol)} · 截至2026年10月26日的实际K线、成交量与指标原图"></button><p class="chart-load-error" hidden>图形载入失败，请使用下方原图链接查看；不能将空白当作没有数据。</p><figcaption><button data-image="${safe(s.symbol)}">点击图形放大 ↗</button><a href="${safe(s.chart_url)}" target="_blank" rel="noopener">单独打开原图</a><small>日线截至10月26日 · 非实时分时</small></figcaption></figure>`:'<div class="chart-load-error">本股原图未绑定，无法展示；请勿将缺图当作未出现结构。</div>'}
function thumbnailFailed(img){img.hidden=true;const figure=img.closest('.chart-preview');if(figure){figure.querySelector('.chart-load-error').hidden=false;figure.querySelector('.chart-preview-button').hidden=true}}
function card(s){const u=overlay(s),down=u&&number(u.price)<number(s.current),bad=u&&(u.above===false||u.gate==='THREE_GATES_FAILED');return `<article class="review-card" data-symbol="${safe(s.symbol)}"><div class="card-heading"><div><div class="card-group">${safe(groups.find(g=>g[0]===s.classification)?.[1]||'UNKNOWN')} · 未认证买点</div><h2>${safe(s.name)}</h2><small>${safe(s.symbol)}</small></div><div class="card-price">${f(latestQuote(s)?.price)}<small>最新全85快照<br>源 ${safe(time(latestQuote(s)?.quote_timestamp))}</small></div></div>${latestBlock(s)}${u?`<div class="overlay ${down||bad?'negative':''}"><strong>历史 ${safe(time(u.time))} ${safe(u.scope)}：${f(s.current)} → ${f(u.price)}</strong><br>${bad?'已不满足原三门条件，降级待复核':down?'当时较13:08回落；当前以最新框为准':'局部价格变化，不等于首次承接认证'}${u.amount!==null?` · 累计额 ${f(number(u.amount)/1e8,3)}亿元`:''}${['002543.SZ','301486.SZ'].includes(s.symbol)?`<br><strong>历史位置反证：${safe(s.support_wait)}</strong><br>仅静态QFQ参考比较，公司事件坐标未准入；三门仍通过不等于承接确认。`:''}</div>`:''}<div class="card-metrics"><span>基准累计额 ${f(number(s.amount_yuan)/1e8,3)}亿元</span><span>今开 ${f(s.open)}</span><span>K高 ${f(s.key_high)}</span><span>主锚 ${safe(s.main_anchor_date)}</span></div><div class="card-section"><h3>01 / 为什么归入这一类</h3><p>${safe(s.today_start_reason)}</p></div><div class="card-section"><h3>02 / 原复核等待条件（结合最新报价）</h3><p>${safe(s.support_wait)}</p></div><div class="card-section risk"><h3>03 / 反证 · 不能忽略</h3><p>${safe(s.counter)}</p>${s.ST_independent_tag==='True'?'<p>ST独立风险标签：不因三门通过而豁免。</p>':''}${s.known_D26_buy_sell_conflict_4?'<p>原买卖信号同现，不能自动放行。</p>':''}</div><div class="card-actions">${s.chart_url?`<button data-image="${safe(s.symbol)}">看原图 ↗</button>`:'<span>原图UNKNOWN</span>'}${s.history18?`<a href="history18.html?showExcluded=1#${safe(s.symbol)}">历史18统计 →</a>`:`<span>${s.history24?'本轮历史见下方':'完整历史统计未接入'}</span>`}</div><details class="card-evidence"><summary>关键位置与图证据</summary><p>实体底 ${f(s.key_body_low)} / 最低 ${f(s.key_low)}。静态QFQ参考；公司事件坐标准入未核。图截至10月26日，不是分时图。</p><p>${safe(s.view_scope)}<br>PNG SHA256 ${safe(s.chart_sha256)}</p><p>${safe(s.formula_sell_risk_note||'原风险未由三门豁免。')}</p></details>${historyBlock(s)}</article>`}
function bindOriginal(){document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const s=pack.stocks.find(x=>x.symbol===b.dataset.image);E('modalImageError').hidden=true;E('reviewImage').hidden=false;E('reviewImage').onerror=()=>{E('reviewImage').hidden=true;E('modalImageError').hidden=false};E('reviewImage').src=s.chart_url;E('reviewImage').alt=s.name+' · 截至10月26日的实际原图';E('imageTitle').textContent=s.name+' '+s.symbol+' · '+s.view_scope;E('imageOpen').href=s.chart_url;E('imageDialog').showModal()})}
function fillOriginalSignals(c){const r=c.chartRows.at(-1),v=r.values||{},stock=pack.stocks.find(s=>s.symbol===c.symbol),lineDate=stock?.displayProjection?.line_asof||r.date;E('signals').innerHTML=`<span class="pill">原字段日期 ${safe(r.date)}${stock?.displayProjection?.admitted===false?' · D27未准入':''}</span>`+['一级买点','二级买点','卖点'].map(k=>`<span class="pill">${safe(k)} ${v[k]===true?'已触发':v[k]===false?'未触发':'UNKNOWN'}</span>`).join('');E('coverage').textContent=`图示 ${c.chartRows.length}根 · ${c.chartRows[0].date}—${r.date}；原字段读取，不重算；新信号不冒昨日名单命中。`;E('levels').innerHTML=[['关键K实体底',stock?.key_body_low,'20261026'],['关键K最低',stock?.key_low,'20261026'],['白线',v['白线'],lineDate],['黄线',v['黄线'],lineDate],['BBI',v.BBI,lineDate],['主关键K高',stock?.key_high,'20261026']].map(([k,x,asof])=>`<article class="level"><span>${safe(k)}</span><strong>${f(x)}</strong><small>${safe(asof)} QFQ研究参考</small></article>`).join('')}

function structureReviewBlock(s){const r=s.structureReview;if(!r)return '';return `<details class="card-evidence" open><summary>本日r2逐图结构研究 · 非买点认证</summary><p>${safe(r.category)} · ${safe(r.latest_main_anchor_phase)}</p><p>${safe(r.visual_rationale_and_counterevidence)}</p><p>条件式阳实体覆盖昨日阴实体：${r.conditional_D27_body_engulfs_D26_bear_body===true?'是（仅几何）':'未满足'}；全K覆盖：${r.conditional_D27_full_range_covers_D26_bear_range===true?'是（仅几何）':'未满足'}。坐标执行准入、分钟承接路径、买点确认均未认证。</p><p>实际审图 ${safe(r.visible_bars)}根，截至${safe(r.chart_last_date)}；view UTC ${safe(r.viewed_utc_window)}。不是全部历史看图或全市场模式认证。</p><p>原式完整历史统计与公告财务未在此重验；Top200赢家交集存在选择偏差，不能推出市场偏好/胜率。</p><code>研究源 SHA256 ${safe(r.source_sha256)} / 图证据 ${safe(r.view_sha256)}</code></details>`}
function fillTemplate(s){E('price').textContent=f(latestQuote(s)?.price);E('quoteTime').textContent=time(latestQuote(s)?.quote_timestamp);E('why').textContent=s.today_start_reason;E('wait').textContent=s.support_wait;E('invalidate').textContent='失效与反证：'+s.counter;E('counter').textContent=s.counter;E('turnoverDetail').innerHTML=latestBlock(s)+'<small>下方判断与等待条件来自历史复核，须结合本框收盘后快照；不把旧失位或旧承接当当前认证。</small>';E('historyStatus').textContent=s.history24?'限定原式统计已核':'未接入';E('historical').innerHTML=structureReviewBlock(s)+historyBlock(s);E('percentiles').innerHTML='<div class="unknown">本轮85未绑定价格分位统计；UNKNOWN不等于零。</div>';E('eventStatus').textContent='待核';E('events').innerHTML='<div class="unknown">本轮未绑定逐股行业催化与财务原件，不推定没有风险。</div>';E('holderStatus').textContent='待核';E('holders').innerHTML='<div class="unknown">本轮未绑定连续可比股东户数与公告时点。</div>';E('missingCount').textContent='研究边界与缺口';E('missing').textContent='公司事件坐标准入未核；非实时，不保证成交。';E('evidence').textContent=s.view_scope+(datasetConfig.kind==='breakout41'?'；轻量图数据SHA256 ':'；PNG SHA256 ')+s.chart_sha256;window.renderResearchModules(s);E('signals').textContent='原式字段载入中';E('levels').innerHTML='';E('coverage').textContent='';E('liveCards').innerHTML=''}
function clearWorkbench(message){window.Chart85.clear();chartLoadToken++;selectedSymbol='';E('content').hidden=true;E('loading').hidden=false;E('loading').textContent=message;E('chart85Panel').hidden=true;E('chartReadout').textContent='';const cv=E('chart');cv.getContext('2d').clearRect(0,0,cv.width,cv.height);E('liveCards').innerHTML=''}
function navigateHash(){let h='';try{h=decodeURIComponent(typeof location==='undefined'?'':location.hash.slice(1))}catch(e){clearWorkbench('股票代码链接无效，旧图已清空。');return}if(!h){render();return}const found=pack.stocks.find(s=>s.symbol===h||s.symbol.split('.')[0]===h);if(!found){clearWorkbench('未知股票代码 '+h+'，不在当前绑定名单内，旧图已清空。请从左侧选择有效股票。');return}selectedSymbol=found.symbol;category='all';if(!gatePass(found)){showRetired=true;E('showRetired').checked=true}query='';E('liveSearch').value='';render()}
async function selectWorkbench(s){if(!s||!pack.stocks.some(x=>x.symbol===s.symbol)){clearWorkbench('未知股票代码，旧图已清空。请从左侧选择有效股票。');return}window.Chart85.clear();selectedSymbol=s.symbol;E('loading').hidden=true;E('content').hidden=false;const token=++chartLoadToken;E('stockName').textContent=s.name;E('stockCode').textContent=s.symbol;E('stockTier').textContent=groups.find(g=>g[0]===s.classification)?.[1]||'UNKNOWN';E('identityMeta').textContent=`收盘后冻结价 ${f(latestQuote(s)?.price)} · 来源 ${time(latestQuote(s)?.quote_timestamp)}；图/线截至 ${s.displayProjection?.chart_last_date||'20261026'}，分位截至 ${s.pricePosition85?.asof||'UNKNOWN'}；${s.displayProjection?.admitted===true?'D27限定展示准入，非交易认证':s.displayProjection?.admitted===false?'D27未准入，保留D26并标UNKNOWN':'固定QFQ历史参考'}。`;fillTemplate(s);E('originalImage').textContent='D26原审图（历史附件）';E('originalImage').hidden=!s.chart_url;if(s.chart_url)E('originalImage').href=s.chart_url;E('chart85Panel').hidden=true;E('chartReadout').textContent='';E('chart').getContext('2d').clearRect(0,0,E('chart').width,E('chart').height);E('chart85Unknown').hidden=false;E('chart85Unknown').textContent='正在读取 '+s.name+' 的实际缓存K线…';document.querySelectorAll('[data-stock85]').forEach(b=>b.classList.toggle('active',b.dataset.stock85===s.symbol));try{let c=chartCache.get(s.symbol);if(!c){const r=await fetch(s.displayProjection?(datasetConfig.displayRoot||'')+s.displayProjection.chart_path:(datasetConfig.chartBase||'chartdata85/')+s.symbol+'.json');if(!r.ok)throw Error('图形文件未正常返回');c=await r.json();if(c.symbol!==s.symbol||!Array.isArray(c.chartRows)||!c.chartRows.length)throw Error('图形身份或数据校验失败');chartCache.set(s.symbol,c)}if(token!==chartLoadToken||selectedSymbol!==s.symbol)return;E('chart85Panel').hidden=false;E('chart85Unknown').hidden=true;fillOriginalSignals(c);window.Chart85.setStock({...s,chartRows:c.chartRows,anchor:{date:s.main_anchor_date,body:s.key_body_low,low:s.key_low}})}catch(e){if(token!==chartLoadToken)return;E('chart85Panel').hidden=true;E('chart85Unknown').innerHTML='本股交互图未能载入：'+safe(e.message)+'。'+(s.chart_url?'<a href="'+safe(s.chart_url)+'" target="_blank" rel="noopener">打开真实原图</a>':'本股没有已绑定PNG原图')+'；不能以其他股票图替代。'}}
function render(){const rows=pack.stocks.filter(s=>(showRetired||gatePass(s))&&(category==='all'||s.classification===category)&&(`${s.name}${s.symbol}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>Number(!!overlay(b))-Number(!!overlay(a)));E('scopeCaption').textContent=`显示 ${rows.length} / 原${expectedStocks}只；默认仅最新研究条件观察；K几何PROVISIONAL。旧分类不变，非买入排序。`;E('stock85List').innerHTML=rows.map(s=>`<button class="stock-item" data-stock85="${safe(s.symbol)}"><span><strong>${safe(s.name)}</strong><small>${safe(s.symbol)}</small></span><span>${f(latestQuote(s)?.price)}<small>${datasetConfig.kind==='breakout41'?'超高源名单 · 路径待核':gatePass(s)?'条件观察 · 未认证':'暂退 / 待核'}</small></span></button>`).join('')||'<p class="caption">该筛选下没有股票。</p>';if(datasetConfig.kind==='breakout41')E('scopeCaption').textContent=`显示 ${rows.length} / 原41只，Top200与13:08超高名单交集；不替换原85，不认证回踩反包。`;document.querySelectorAll('[data-stock85]').forEach(b=>b.onclick=()=>selectWorkbench(pack.stocks.find(s=>s.symbol===b.dataset.stock85)));document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));if(rows.length)selectWorkbench(rows.find(s=>s.symbol===selectedSymbol)||rows.find(s=>s.symbol==='300770.SZ')||rows[0]);else{chartLoadToken++;selectedSymbol='';E('chart85Panel').hidden=true;E('chart85Unknown').hidden=false;E('chart85Unknown').textContent='当前筛选没有条目；未显示旧股票图形。';E('stockName').textContent='没有符合当前筛选的股票';E('stockCode').textContent='';E('identityMeta').textContent='请更改分类、搜索或显示暂退。';E('content').hidden=true}}
fetch(datasetConfig.dataUrl||'live85_data.json').then(r=>{if(!r.ok)throw Error('冻结数据不可读');return r.json()}).then(async d=>{if(!datasetConfig.displayUrl)return d;const dr=await fetch(datasetConfig.displayUrl);if(!dr.ok)throw Error('D27展示准入包无法读取');const dp=await dr.json();if(dp.stocks?.length!==126||new Set(dp.stocks.map(x=>x.symbol)).size!==126)throw Error('126展示身份校验失败');const dm=new Map(dp.stocks.map(x=>[x.symbol,x]));for(const stock of d.stocks){const v=dm.get(stock.symbol);if(!v||!v.chart_path||![20261026,20261027].includes(Number(v.chart_last_date)))throw Error('逐股展示准入字段缺失');stock.displayProjection=v;if(v.price_position)stock.pricePosition85=v.price_position;}d.meta.display_revision=dp.meta;return d}).then(async d=>{if(!datasetConfig.reviewUrl)return d;const rr=await fetch(datasetConfig.reviewUrl);if(!rr.ok)throw Error('本日结构修订无法读取');const review=await rr.json();if(review.stocks?.length!==expectedStocks||new Set(review.stocks.map(x=>x.symbol)).size!==expectedStocks||review.stocks.some(x=>!d.stocks.some(y=>y.symbol===x.symbol)))throw Error('结构修订身份校验失败');const map=new Map(review.stocks.map(x=>[x.symbol,x]));for(const stock of d.stocks){const r=map.get(stock.symbol);stock.structureReview={...r,source_sha256:review.meta.source_sha256};stock.originalResearch={why:stock.today_start_reason,wait:stock.support_wait,counter:stock.counter};stock.today_start_reason='本日r2逐图研究：'+r.category+'；'+r.latest_main_anchor_phase+'。'+r.visual_rationale_and_counterevidence+'\n原13:08来源：'+stock.originalResearch.why;stock.counter=stock.originalResearch.counter+'\n本次逐图反证：'+r.visual_rationale_and_counterevidence+'；不是整段首次启动或买点确认，分钟路径未核。'}return d}).then(d=>{if(d.stocks?.length!==expectedStocks||new Set(d.stocks.map(s=>s.symbol)).size!==expectedStocks)throw Error(expectedStocks+'身份校验失败');pack=d;E('showRetired').checked=showRetired;window.Chart85.bind();const cc=d.meta.close_snapshot;E('latestCounts').textContent=cc?`D27收盘后原85：${d.stocks.filter(gatePass).length}条件观察 / ${d.stocks.filter(s=>!gatePass(s)).length}暂退或待核；原分类24/36/24/1保留。原900另算：几何未超${cc.all900_counts?.PROVISIONAL_AT_OR_BELOW??'UNKNOWN'}、超高${cc.all900_counts?.PROVISIONAL_ABOVE_OBSERVE_NO_CHASE??'UNKNOWN'}、≤今开${cc.all900_counts?.NOT_ABOVE_OPEN??'UNKNOWN'}、未达额${cc.all900_counts?.BELOW_100M??'UNKNOWN'}；非同一85池，非确认买点。`:`历史13:32固定85研究快照`;if(datasetConfig.kind==='breakout41')E('latestCounts').textContent=d.meta.scope_caption||'固定41超高源名单；不是全部900超高股，也不是已确认回踩反包。';E('showRetired').onchange=e=>{showRetired=e.target.checked;render()};E('counts').innerHTML=groups.map(([g,t])=>`<span><b>${d.stocks.filter(s=>s.classification===g).length}</b>${safe(t)}</span>`).join('');E('categoryTabs').innerHTML=[...groups,['all','全部'+expectedStocks]].map(([g,t])=>`<button data-category="${safe(g)}">${safe(t)}</button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});E('liveSearch').oninput=e=>{query=e.target.value;render()};E('closeImage').onclick=()=>E('imageDialog').close();E('deliveryEvidence').textContent=`85原图SHA逐一校验；UI源SHA256 ${d.meta.source_sha256}；清单SHA256 ${d.meta.chart_manifest_sha256}。读取范围：85唯一身份，分类计数24/36/24/1，旧18独立保留；局部更新不扩大范围。`;if(datasetConfig.kind==='breakout41')E('deliveryEvidence').textContent='41精确名单源SHA256 '+d.meta.source_sha256+'；轻量图manifest SHA256 '+d.meta.chart_manifest_sha256+'。40只180根、301655.SZ仅42根；日线仍D26，原字段读取。无PNG时不伪造原图链接，原85保持独立。';if(d.meta.display_revision)E('deliveryEvidence').textContent='r3限定展示：全126中123图指标/分位至D27，3股保留D26+UNKNOWN。根数以每股图示覆盖为准，非一律180。原关键K锚/来源池仍D26，PNG仅历史附件。准入SHA '+d.meta.display_revision.admission_sha256+'；非class1复权语义UNVERIFIED，不等交易认证。';if(d.meta.display_revision)E('latestCounts').textContent='本次126图指标：123已更新D27 / 3保留D26待核；本池'+d.stocks.filter(s=>s.displayProjection?.admitted).length+'只D27，'+d.stocks.filter(s=>!s.displayProjection?.admitted).length+'只D26。非class1复权语义UNVERIFIED，限定展示不等交易认证。 '+E('latestCounts').textContent;window.addEventListener('hashchange',navigateHash);navigateHash()}).catch(e=>{E('liveCards').textContent='无法正常读取本批数据：'+e.message+'。不展示伪造占位结果。';console.error(e)});
